sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    g_form.hideFieldMsg('seats', true);
    if (newValue === '') {
        return;
    }

    var seatsVal = parseInt(newValue, 10);
    var filledStr = g_form.getValue('filled');
    var filledVal = parseInt(filledStr, 10);

    if (!isNaN(seatsVal) && !isNaN(filledVal) && seatsVal > 0) {
        if (filledVal >= seatsVal) {
            g_form.showFieldMsg('seats', 'Warning: Filled count (' + filledVal + ') has reached or exceeded the seat limit (' + seatsVal + ').', 'warning');
        }
    }
}
